//var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조. 
// scwin.fr_MktId = $c.lce.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
// dialog 호출용 함수
// 발행기관목록관련
scwin.vScrenID = "ULDSTF07407.gfm";
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vListBzTpCd = "";
scwin.clickListBzDtlTpCd = "";
scwin.clickAdjReqProcsNo = "";

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    //----W-Craft WebSquare 변환 확인: Provider----//
    // var parentWin = frame.Provider("../");
    scwin.parentWin = $p.getParentWindow();
    // scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vBzProcsNo = "20260320000007" //TODO: TEST (이전화면에서 가져오는 값)
    scwin.vListBzTpCd = "210";
    scwin.listSync();
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/* 닫기 버튼 */
scwin.btn_Close_onclick = function(e) {
    $c.win.closePopup();
};

scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    scwin.setBzProcsNo(rowIndex);
    //alert ( clickAdjReqProcsStatCd );
    if ("funcAcpt" === columnId) {
        let vAnswer = confirm('승인처리 하시겠습니까?');
        if (vAnswer === true) {
            LastJob = "승인";
            scwin.trs("35");
        }
    } else if ("funcRjct" === columnId) {
        let vAnswer = confirm('불가처리 하시겠습니까?');
        if (vAnswer === true) {
            LastJob = "불가";
            scwin.trs("36");
        }
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/* 조회 후 처리 */
scwin.sbm_selectList_submitdone = function (e) {
    dlt_selectListRes.setJSON(e.responseJSON.body);
};

/* 조회 에러 처리 */
scwin.sbm_selectList_submiterror = function (e) {
    $c.win.alert(dlt_selectListRes);
};

/* 접수 또는 반려처리 후 처리 */
scwin.sbm_process_submitdone = function (e) {
    $c.lce.fn_alertMsg('S');
    scwin.listSync();
    scwin.parentRefresh();
};

/* 접수 또는 반려처리 에러처리 */
scwin.sbm_process_submiterror = function (e) {
    $c.lce.fn_alertMsg('F');
    $c.win.alert(trs_Save);
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/lstinvstg/LstInvstgCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

	// //----W-Craft WebSquare 변환 확인: reset----//

    const reqMap = {
        bzProcsNo: scwin.vBzProcsNo, //업무처리번호
        listInvstgBzTpCd: scwin.vListBzTpCd, //상장심사업무구분코드
    };
    $c.sbm.execute(sbm_selectList, reqMap);
};

scwin.setBzProcsNo = function(obj) {
    scwin.clickListBzDtlTpCd = dlt_selectListRes.getCellData(eval(obj), "listBzDtlTpCd");
    scwin.clickAdjReqProcsNo = dlt_selectListRes.getCellData(eval(obj), "adjReqProcsNo");
    //alert(clickListBzDtlTpCd);
};

//접수 또는 반려처리
scwin.trs = function(listProcsStatCd) {
    // trs_Save.Action = $c.lce.fn_encodeNSession("/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=processAdjReq");
    // trs_Save.KeyName = "toinb_dataid4";
    // trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    // trs_Save.Parameters = "TRS_IDX=U" 
    // + ",LIST_PROCS_STAT_CD=" + listProcsStatCd 
    // + ",BZ_PROCS_NO=" + scwin.vBzProcsNo 
    // + ",LIST_BZ_TP_CD=" + scwin.vListBzTpCd 
    // + ",LIST_BZ_DTL_TP_CD=" + scwin.clickListBzDtlTpCd 
    // + ",PROCS_EMP_NO=" + js_emp_no 
    // + ",ADJ_REQ_PROCS_NO=" + scwin.clickAdjReqProcsNo;

	// //----W-Craft WebSquare 변환 확인: Post----//
    // trs_Save.Post();

    dma_processReq.set("bzProcsNo", scwin.vBzProcsNo);
    dma_processReq.set("listBzTpCd", scwin.vListBzTpCd);
    dma_processReq.set("listBzDtlTpCd", scwin.clickListBzDtlTpCd);
    dma_processReq.set("adjReqProcsNo", scwin.clickAdjReqProcsNo);
    dma_processReq.set("listProcsStatCd", listProcsStatCd);
    dma_processReq.set("procsEmpNo", $c.stf.getUserInfo("empNo"));

    $c.sbm.execute(sbm_process, dma_processReq.getJSON());
};

scwin.parentRefresh = function() {

	// //----W-Craft WebSquare 변환 확인: fr_fn_list_sync----//

	// //----W-Craft WebSquare 변환 확인: Provider----//
    // var fr_fn_list_sync = frame.Provider("../").fn_list_sync;

	// //----W-Craft WebSquare 변환 확인: fr_fn_list_sync----//
    // fr_fn_list_sync();

    //이전 화면을 다시 submission 하는 로직인 것 같음
    // TODO: (확인필요) 끝나고 나서 07400 화면이 다시 팝업으로 뜨던데, 이것 떄문인가?
    scwin.parentWin.fn_list_sync();
};
